import { plainDate, plainYearMonth } from '@absoluteui/core';
import { BusinessCalendar, type BusinessCalendarChangeDetail } from '@absoluteui/components/business-calendar';

const host = document.createElement('div');
document.body.append(host);
BusinessCalendar.create(host, {
  label: 'London office',
  month: plainYearMonth(2026, 12),
  months: 2,
  editable: true,
  definition: {
    holidays: [
      { date: plainDate(2026, 12, 25), name: 'Christmas Day', yearly: true },
      { date: plainDate(2026, 12, 28), name: 'Boxing Day (substitute)' },
    ],
  },
});
host.addEventListener('aui-change', (event) => {
  const { definition } = (event as CustomEvent<BusinessCalendarChangeDetail>).detail;
  host.dataset.exceptions = String(definition.exceptions?.length ?? 0);
});

import { plainDate, plainTime } from '@absoluteui/core';
import { createBusinessCalendar } from '@absoluteui/components/business-calendar';

const calendar = createBusinessCalendar({
  workingDays: [1, 2, 3, 4, 5],
  weekdayHours: { '5': [{ start: plainTime(9), end: plainTime(13) }] },
  holidays: [{ date: plainDate(2026, 1, 1), name: "New Year's Day", yearly: true }],
});
const due = calendar.addWorkingDays(plainDate(2025, 12, 30), 3);
const days = calendar.workingDaysBetween(plainDate(2026, 1, 1), plainDate(2026, 2, 1));
const hours = calendar.workingIntervals(plainDate(2026, 1, 2), 'Europe/London');
export const summary = { due, days, hours };
